public final class MainActivity extends XbsActivity {
    private static final int REQUEST_NOTIFICATIONS = 43;
    private static final String[] PAGES = {"Overview", "Events", "Processes", "Activity", "Settings"};
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private UiKit ui;
    private int page;
    private boolean registered;
    private RunFilter runFilter = RunFilter.ALL;
    private UiUpdateDebouncer updateDebouncer;
    private long createStartedAt;

    private final BroadcastReceiver updates = new BroadcastReceiver() {
        @Override public void onReceive(Context context, Intent intent) { if(updateDebouncer!=null)updateDebouncer.request(); }
    };

    @Override protected void onCreate(android.os.Bundle state) {
        createStartedAt=SystemClock.elapsedRealtime();
        super.onCreate(state); new NotificationController(this); updateDebouncer=new UiUpdateDebouncer(this,this::rebuild);
        page = IntentSecurityPolicy.page(getIntent(), "page", getIntent().hasExtra("run_id") ? 3 : AppSettings.page(this), PAGES.length);
        if (page < 0 || page >= PAGES.length) page = 0;
        rebuild(); PerformanceStore.recordStartup(this,SystemClock.elapsedRealtime()-createStartedAt); checkRoot(false);
        if (AppSettings.monitorEnabled(this)) EventMonitorService.start(this); else refreshState(false);
    }

    @Override protected void onNewIntent(Intent intent) { super.onNewIntent(intent); setIntent(intent); page=IntentSecurityPolicy.page(intent,"page",intent.hasExtra("run_id")?3:page,PAGES.length); rebuild(); }
    @Override protected void onStart() { super.onStart(); if(!registered){IntentFilter filter=new IntentFilter();filter.addAction(RunStore.ACTION_UPDATED);filter.addAction(XbsStateStore.ACTION_STATE_UPDATED);ContextCompat.registerReceiver(this,updates,filter,ContextCompat.RECEIVER_NOT_EXPORTED);registered=true;} }
    @Override protected void onStop() { if(registered){unregisterReceiver(updates);registered=false;}super.onStop(); }
    @Override protected void onDestroy() { if(updateDebouncer!=null)updateDebouncer.cancel();executor.shutdownNow(); super.onDestroy(); }

    private void rebuild(){long started=SystemClock.elapsedRealtime();ui=new UiKit(this);getWindow().setStatusBarColor(ui.palette.background);getWindow().setNavigationBarColor(ui.palette.background);View view=root();setXbsContentView(view);revealRunFromIntent(view);PerformanceStore.recordRebuild(this,SystemClock.elapsedRealtime()-started);}
    private View root(){int width=getResources().getConfiguration().screenWidthDp;AdaptiveLayoutPolicy.WidthClass widthClass=AdaptiveLayoutPolicy.classify(width);boolean rail=AdaptiveLayoutPolicy.useNavigationRail(width);LinearLayout shell=new LinearLayout(this);shell.setOrientation(rail?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);shell.setBackgroundColor(ui.palette.background);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setBackgroundColor(ui.palette.background);LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.VERTICAL);int inset=ui.dp(AdaptiveLayoutPolicy.contentInsetDp(width));header.setPadding(inset,ui.dp(17),inset,ui.dp(12));header.addView(ui.text("XBS COMPANION",12,ui.palette.orange,true));TextView title=ui.primaryTitle(PAGES[page]);header.addView(title);header.addView(ui.text(subtitle(),13,ui.palette.muted,false));body.addView(header);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(content());body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));FrameLayout bodyHost=new FrameLayout(this);bodyHost.setBackgroundColor(ui.palette.background);int maxContentDp=AdaptiveLayoutPolicy.maxContentWidthDp(width);int availableBodyDp=Math.max(0,width-(rail?168:0));boolean constrained=widthClass==AdaptiveLayoutPolicy.WidthClass.EXPANDED&&maxContentDp>0&&availableBodyDp>maxContentDp;FrameLayout.LayoutParams bodyParams=new FrameLayout.LayoutParams(constrained?ui.dp(maxContentDp):-1,-1,Gravity.CENTER_HORIZONTAL);bodyHost.addView(body,bodyParams);UiQualityStore.recordLayout(this,width,widthClass,rail,maxContentDp,widthClass!=AdaptiveLayoutPolicy.WidthClass.EXPANDED||constrained||availableBodyDp<=maxContentDp);if(rail){shell.addView(nav(true),new LinearLayout.LayoutParams(ui.dp(168),-1));shell.addView(bodyHost,new LinearLayout.LayoutParams(0,-1,1));}else{shell.addView(bodyHost,new LinearLayout.LayoutParams(-1,0,1));shell.addView(nav(false));}return shell;}
    private String subtitle(){switch(page){case 1:return "Manage protected built-in and custom XBS event profiles.";case 2:return "Live root process CPU, memory, app ownership and XBS rules.";case 3:return "Runtime transitions and technical command results.";case 4:return "Root, caching, notifications, Tasker and monitoring behavior.";default:return "Live XBS runtime state, simultaneous events and primary controls.";}}
    private View nav(boolean rail){LinearLayout row=new LinearLayout(this);row.setOrientation(rail?LinearLayout.VERTICAL:LinearLayout.HORIZONTAL);row.setPadding(ui.dp(6),ui.dp(8),ui.dp(6),ui.dp(8));row.setBackgroundColor(ui.palette.surface);String[] symbols={"●","⚡","▦","◷","⚙"};for(int i=0;i<PAGES.length;i++){final int target=i;Button b=ui.navButton(symbols[i],PAGES[i],i==page,v->{page=target;AppSettings.setPage(this,target);rebuild();});row.addView(b,rail?new LinearLayout.LayoutParams(-1,ui.dp(58)):new LinearLayout.LayoutParams(0,ui.dp(58),1));}return row;}
    private View content(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(ui.dp(16),0,ui.dp(16),ui.dp(30));if(page==0)overview(c);else if(page==1)events(c);else if(page==2)processes(c);else if(page==3)activity(c);else settingsPage(c);return c;}

    private void overview(LinearLayout c){XbsSnapshot s=XbsStateStore.current(this);RootStatus root=XbsRootApi.cachedRootStatus(this);c.addView(ui.sectionTitle("Runtime"));LinearLayout hero=ui.surface();hero.addView(ui.text(s.headline(),24,statusColor(s),true));hero.addView(ui.text(s.summary(),14,ui.palette.muted,false));hero.addView(actionRow(s));hero.addView(ui.secondaryButton("Quick actions",v->QuickActionsSheet.show(this)));hero.addView(ui.secondaryButton("Refresh now",v->refreshState(true)));c.addView(hero);activeOverview(c);
        c.addView(ui.sectionTitle("Event management"));LinearLayout manage=ui.surface();manage.addView(ui.text("Manage XBS events",18,ui.palette.orange,true));manage.addView(ui.text("Built-in events can be edited and cloned but never renamed or deleted. Custom events support full CRUD.",13,ui.palette.muted,false));manage.addView(ui.button("Create custom event",ui.palette.green,v->openEventEditor("",false)));manage.addView(ui.secondaryButton("Open event manager",v->openEventManager()));manage.addView(ui.secondaryButton("Edit default essentials",v->startActivity(new Intent(this,XbsEssentialsActivity.class))));c.addView(manage);
        c.addView(ui.sectionTitle("Active events"));if(s.active.isEmpty()){LinearLayout empty=ui.surface();empty.addView(ui.text("No active events",17,ui.palette.text,true));empty.addView(ui.text("XBS supports several simultaneous active events, such as charging and low power.",13,ui.palette.muted,false));empty.addView(ui.button("Open events",ui.palette.orange,v->{page=1;AppSettings.setPage(this,1);rebuild();}));c.addView(empty);}else{LinearLayout summary=ui.surface();summary.addView(ui.text(s.active.size()+" simultaneously active",17,ui.palette.green,true));summary.addView(ui.text(XbsSnapshot.join(s.active),13,ui.palette.muted,false));summary.addView(ui.secondaryButton("Open all event controls",v->startActivity(new Intent(this,EventControlActivity.class))));c.addView(summary);for(String name:s.active)c.addView(eventCard(name,true));}
        c.addView(ui.sectionTitle("Health"));LinearLayout health=ui.surface();health.addView(statusLine("Root",root.summary(),root.granted?ui.palette.green:root.checked?ui.palette.red:ui.palette.yellow));health.addView(statusLine("XBS runtime",s.available?"Available":"Unavailable",s.available?ui.palette.green:ui.palette.red));health.addView(statusLine("Event monitor",AppSettings.monitorEnabled(this)?"Running":"Stopped",AppSettings.monitorEnabled(this)?ui.palette.green:ui.palette.yellow));health.addView(statusLine("Tasker reactions",AppSettings.taskerEventsEnabled(this)?"Enabled":"Disabled",AppSettings.taskerEventsEnabled(this)?ui.palette.green:ui.palette.muted));health.addView(ui.secondaryButton("Check root access",v->checkRoot(true)));c.addView(health);}

    private LinearLayout actionRow(XbsSnapshot s){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button pause=ui.button(s.paused?"Resume":"Pause",s.paused?ui.palette.green:ui.palette.yellow,v->run(s.paused?"resume":"pause",""));Button safe=ui.button(s.safeMode?"Exit safe":"Safe mode",s.safeMode?ui.palette.green:ui.palette.red,v->run(s.safeMode?"safe_off":"safe_on",""));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,ui.dp(5),ui.dp(4),0);row.addView(pause,p);LinearLayout.LayoutParams p2=new LinearLayout.LayoutParams(0,-2,1);p2.setMargins(ui.dp(4),ui.dp(5),0,0);row.addView(safe,p2);return row;}

    private void events(LinearLayout c){XbsSnapshot s=XbsStateStore.current(this);c.addView(ui.sectionTitle("Create and manage"));LinearLayout manager=ui.surface();manager.addView(ui.text("Event profiles",19,ui.palette.orange,true));manager.addView(ui.text("Lists can be edited manually or with installed-app and live-process pickers.",13,ui.palette.muted,false));manager.addView(ui.button("Create custom event",ui.palette.green,v->openEventEditor("",false)));manager.addView(ui.secondaryButton("Open full event manager",v->openEventManager()));manager.addView(ui.secondaryButton("Edit template defaults",v->openTemplateEditor()));manager.addView(ui.secondaryButton("Edit default essentials",v->startActivity(new Intent(this,XbsEssentialsActivity.class))));c.addView(manager);
        c.addView(ui.sectionTitle("Active simultaneously"));if(s.active.isEmpty())c.addView(messageCard("No active events","XBS has no active event profiles."));else for(String name:s.active)c.addView(eventCard(name,true));c.addView(ui.sectionTitle("Available"));if(s.inactive.isEmpty())c.addView(messageCard("No event catalog yet","Refresh status while the XBS daemon is running."));else for(String name:s.inactive)c.addView(eventCard(name,false));c.addView(ui.sectionTitle("Runtime tools"));LinearLayout tools=ui.surface();tools.addView(ui.button("Reload configuration",ui.palette.orange,v->run("reload","")));tools.addView(ui.secondaryButton("Validate configuration",v->run("validate","")));tools.addView(ui.secondaryButton("Refresh event list",v->refreshState(true)));tools.addView(ui.secondaryButton("Quick actions",v->QuickActionsSheet.show(this)));tools.addView(ui.secondaryButton("Command Center",v->startActivity(new Intent(this,CliCommandActivity.class))));c.addView(tools);}

    private View eventCard(String name,boolean active){
        if("template".equals(name)) {
            LinearLayout card=ui.surface();
            card.addView(ui.text("Template defaults",18,ui.palette.yellow,true));
            card.addView(ui.text("Reserved inheritance profile; it is not a runnable event.",12,ui.palette.muted,false));
            card.addView(ui.secondaryButton("Edit template defaults",v->openTemplateEditor()));
            return card;
        }
        LinearLayout card=ui.surface();card.addView(ui.text(XbsSnapshot.pretty(name),18,active?ui.palette.green:ui.palette.text,true));card.addView(ui.text((active?"Currently active":"Available to start")+(XbsConfigApi.isBuiltInEvent(name)?" · built-in":" · custom"),12,ui.palette.muted,false));card.addView(ui.button(active?"Stop event":"Start event",active?ui.palette.red:ui.palette.orange,v->confirmEvent(name,active)));LinearLayout editRow=new LinearLayout(this);editRow.setOrientation(LinearLayout.HORIZONTAL);Button edit=ui.secondaryButton("Edit",v->openEventEditor(name,false));Button clone=ui.secondaryButton("Clone",v->openEventEditor(name,true));LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-2,1);left.setMargins(0,0,ui.dp(4),0);editRow.addView(edit,left);LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,-2,1);right.setMargins(ui.dp(4),0,0,0);editRow.addView(clone,right);card.addView(editRow);if(XbsConfigApi.isBuiltInEvent(name))card.addView(ui.text("Protected default event · deletion and rename disabled",12,ui.palette.yellow,true));else card.addView(ui.button("Delete event",ui.palette.red,v->confirmDeleteEvent(name)));return card;}

    private void processes(LinearLayout c){ProcessSnapshot cached=ProcessRepository.cached(this);c.addView(ui.sectionTitle("Live monitor"));LinearLayout hero=ui.surface();hero.addView(ui.text("CPU, RAM and app ownership",19,ui.palette.orange,true));hero.addView(ui.text("The full monitor samples /proc every two seconds, calculates CPU deltas, maps UID/process names to installed apps, and shows matching XBS process rules.",13,ui.palette.muted,false));hero.addView(ui.button("Open live process monitor",ui.palette.green,v->startActivity(new Intent(this,ProcessMonitorActivity.class))));hero.addView(ui.secondaryButton("Refresh cached sample",v->sampleProcesses()));c.addView(hero);
        c.addView(ui.sectionTitle("Cached sample"));if(!cached.rootAvailable){c.addView(messageCard("No process sample",cached.error));}else{long total=0;for(XbsProcess p:cached.processes)total+=p.rssKb;LinearLayout stats=ui.surface();stats.addView(ui.text(cached.processes.size()+" processes",18,ui.palette.text,true));stats.addView(ui.text("Combined RSS: "+ram(total)+" · cache age "+ageLabel(System.currentTimeMillis()-cached.capturedAt),12,ui.palette.muted,false));if(cached.diagnostics.partial())stats.addView(ui.text("Partial /proc sample: "+cached.diagnostics.summary(),11,ui.palette.yellow,true));c.addView(stats);for(int i=0;i<Math.min(10,cached.processes.size());i++){XbsProcess p=cached.processes.get(i);LinearLayout card=ui.surface();card.addView(ui.text(p.appLabel,16,ui.palette.text,true));card.addView(ui.text(p.packageName.isEmpty()?p.processName:p.packageName+" · "+p.processName,12,ui.palette.muted,false));card.addView(ui.text(String.format(Locale.US,"CPU %.1f%% · RAM %s · PID %d",p.cpuPercent,p.ramLabel(),p.pid),13,ui.palette.green,false));if(!p.ruleEvents.isEmpty())card.addView(ui.text("XBS rules: "+XbsSnapshot.join(p.ruleEvents),11,ui.palette.yellow,true));c.addView(card);}}}

    private void openEventEditor(String name,boolean clone){
        if("template".equals(name)){Toast.makeText(this,"Use Edit template defaults for the reserved template profile",Toast.LENGTH_LONG).show();return;}
        Intent intent=new Intent(this,XbsEventEditorActivity.class);
        intent.putExtra(XbsEventEditorActivity.EXTRA_EVENT,name);
        intent.putExtra(XbsEventEditorActivity.EXTRA_CLONE,clone);
        startActivity(intent);
    }
    private void openTemplateEditor(){
        Intent intent=new Intent(this,XbsEventEditorActivity.class);
        intent.putExtra(XbsEventEditorActivity.EXTRA_EVENT,"template");
        intent.putExtra(XbsEventEditorActivity.EXTRA_TEMPLATE_DEFAULTS,true);
        startActivity(intent);
    }
    private void openEventManager(){startActivity(new Intent(this,XbsConfigActivity.class).putExtra("events_only",true));}
    private void confirmDeleteEvent(String name){if(XbsConfigApi.isBuiltInEvent(name)){Toast.makeText(this,"Built-in events cannot be deleted",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Delete "+XbsSnapshot.pretty(name)+"?").setMessage("Remove this custom event from XtremeBS.json?").setNegativeButton("Cancel",null).setNeutralButton("Keep list files",(d,w)->deleteEvent(name,false)).setPositiveButton("Delete all",(d,w)->deleteEvent(name,true)).show();}
    private void deleteEvent(String name,boolean deleteFiles){Toast.makeText(this,"Deleting event…",Toast.LENGTH_SHORT).show();executor.execute(()->{XbsConfigApi.Result result=XbsConfigApi.deleteEvent(this,name,deleteFiles);runOnUiThread(()->{Toast.makeText(this,result.ok?"Event deleted":result.message,Toast.LENGTH_LONG).show();refreshState(false);});});}
    private void confirmEvent(String name,boolean active){String verb=active?"Stop":"Start";new AlertDialog.Builder(this).setTitle(verb+" "+XbsSnapshot.pretty(name)+"?").setMessage(active?"Only this event will be stopped; other active events remain active.":"This event can run alongside other active XBS events.").setNegativeButton("Cancel",null).setPositiveButton(verb,(d,w)->runCtl(active?"stop":"start",name,active)).show();}

    private void activity(LinearLayout c){c.addView(ui.sectionTitle("Activity tools"));LinearLayout workbench=ui.surface();workbench.addView(ui.text("Search and manage history",18,ui.palette.orange,true));workbench.addView(ui.text("Activity already shows recent evidence here. Open the history tools only when you need search, filters, export, selection, or cleanup.",13,ui.palette.muted,false));workbench.addView(ui.secondaryButton("Search & manage history",v->startActivity(new Intent(this,ActivityWorkbenchActivity.class))));workbench.addView(ui.text("Room records: "+RunStore.all(this).size()+" · retention: "+AppSettings.historyRetention(this)+" · events: "+XbsStateStore.events(this).size(),12,ui.palette.cyan,false));c.addView(workbench);activeCommands(c);c.addView(ui.sectionTitle("Recent event timeline"));List<XbsEvent> events=XbsStateStore.events(this);if(events.isEmpty())c.addView(messageCard("No event changes captured","Enable the event monitor to record XBS transitions."));else for(int i=0;i<Math.min(10,events.size());i++){XbsEvent e=events.get(i);LinearLayout card=ui.surface();card.addView(ui.text(e.message,16,e.isImportant()?ui.palette.yellow:ui.palette.text,true));card.addView(ui.text(DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.MEDIUM).format(new Date(e.timestamp*1000L))+" · "+e.type,12,ui.palette.muted,false));c.addView(card);}commandHistory(c);}

    private void activeOverview(LinearLayout c){List<RunRecord> active=RunStore.active(this);if(active.isEmpty())return;c.addView(ui.sectionTitle("Active root commands"));LinearLayout card=ui.surface();card.addView(ui.text(active.size()==1?"1 command running":active.size()+" commands running",18,ui.palette.green,true));for(int i=0;i<Math.min(2,active.size());i++){RunRecord r=active.get(i);card.addView(ui.text(r.title+" · "+RunDetailFormatter.statusLine(r),12,ui.palette.muted,false));}card.addView(ui.button("Open command activity",ui.palette.orange,v->{page=3;AppSettings.setPage(this,3);rebuild();}));c.addView(card);}
    private void activeCommands(LinearLayout c){c.addView(ui.sectionTitle("Active root commands"));List<RunRecord> active=RunStore.active(this);if(active.isEmpty()){c.addView(messageCard("No active root commands","Foreground XBS commands and cancellation controls appear here while work is running."));return;}for(RunRecord r:active)c.addView(runCard(r));}
    private void commandHistory(LinearLayout c){c.addView(ui.sectionTitle("Command history"));LinearLayout filters=ui.surface();filters.addView(ui.text("Filter: "+runFilter.label+" · "+RunStore.count(this,runFilter)+" shown",16,ui.palette.orange,true));filters.addView(filterRow(RunFilter.ALL,RunFilter.ACTIVE,RunFilter.SUCCEEDED));filters.addView(filterRow(RunFilter.FAILED,RunFilter.TIMED_OUT,RunFilter.CANCELLED));filters.addView(filterRow(RunFilter.OUTPUT));LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button clearFinished=ui.secondaryButton("Clear finished",v->confirmClearFinished());LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-2,1);left.setMargins(0,0,ui.dp(4),0);actions.addView(clearFinished,left);Button clearAll=ui.secondaryButton("Clear all",v->new AlertDialog.Builder(this).setTitle("Clear command history?").setMessage("This removes local run records but does not stop active root commands.").setNegativeButton("Cancel",null).setPositiveButton("Clear",(d,w)->{RunStore.clear(this);rebuild();}).show());LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,-2,1);right.setMargins(ui.dp(4),0,0,0);actions.addView(clearAll,right);filters.addView(actions);c.addView(filters);List<RunRecord> runs=RunStore.filtered(this,runFilter);if(runs.isEmpty())c.addView(messageCard(runFilter.emptyTitle,runFilter.emptyMessage));else for(int i=0;i<Math.min(RunRetentionPolicy.MAX_RECORDS,runs.size());i++)c.addView(runCard(runs.get(i)));}
    private LinearLayout filterRow(RunFilter... filters){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);for(RunFilter filter:filters){Button button=ui.button(filter.label,filter==runFilter?ui.palette.green:ui.palette.surfaceRaised,v->{runFilter=filter;rebuild();});if(filter!=runFilter)button.setTextColor(ui.palette.text);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);params.setMargins(ui.dp(3),0,ui.dp(3),0);row.addView(button,params);}return row;}

    private LinearLayout runCard(RunRecord r){LinearLayout card=ui.surface();boolean active=RunDetailFormatter.isActive(r);int color="failed".equals(r.status)?ui.palette.red:"ok".equals(r.status)?ui.palette.green:active?ui.palette.yellow:ui.palette.text;card.addView(ui.text(r.title,16,color,true));card.addView(ui.text(RunDetailFormatter.cardMessage(r),12,ui.palette.muted,false));card.addView(ui.text(RunDetailFormatter.outputSummary(r),12,ui.palette.cyan,false));LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button details=ui.secondaryButton("View details",v->showRun(r));LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,-2,1);left.setMargins(0,0,ui.dp(4),0);row.addView(details,left);if(active){Button cancel=RunStore.isStaleActive(this,r)?ui.button("Force finalize",ui.palette.red,v->forceFinalize(r)):ui.button("Cancel",ui.palette.red,v->cancelRun(r));LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,-2,1);right.setMargins(ui.dp(4),0,0,0);row.addView(cancel,right);}else if(RunFilter.isRetryable(r)){Button retry=ui.button("Retry",ui.palette.orange,v->retryRun(r));LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,-2,1);right.setMargins(ui.dp(4),0,0,0);row.addView(retry,right);}card.addView(row);return card;}

    private void settingsPage(LinearLayout c){SettingsHubView.render(this,ui,c);}

    private TextView statusLine(String label,String value,int color){TextView t=ui.text(getString(R.string.xbs_status_line, label, value),14,color,false);t.setPadding(0,ui.dp(5),0,ui.dp(5));return t;}
    private LinearLayout messageCard(String title,String text){LinearLayout card=ui.surface();card.addView(ui.text(title,17,ui.palette.text,true));card.addView(ui.text(text,13,ui.palette.muted,false));return card;}
    private int statusColor(XbsSnapshot s){if(!s.available)return ui.palette.red;if(s.safeMode||s.paused)return ui.palette.yellow;return ui.palette.green;}
    private void run(String id,String arg){SuiteAction action=SuiteCatalog.find("xbs",id);if(action==null)return;CommandLaunchResult result=RootCommandRunner.run(this,action,arg,null);Toast.makeText(this,result.started?"XBS action started":result.error,Toast.LENGTH_SHORT).show();}
    private void runCtl(String action,String event,boolean destructive){String command="XBSctl --json "+action+" "+SuiteAction.shellQuote(event);CommandLaunchResult result=RootCommandRunner.runCommand(this,"event_"+action,action+" event","Control one XBS event without affecting other active events",command,destructive,null);Toast.makeText(this,result.started?"XBS event action started":result.error,Toast.LENGTH_SHORT).show();}
    private void refreshState(boolean toast){executor.execute(()->{XbsSnapshot snapshot=XbsRootApi.readSnapshot(this);XbsStateProcessor.process(this,snapshot,false);runOnUiThread(()->{if(toast)Toast.makeText(this,snapshot.available?"XBS status refreshed":snapshot.error,Toast.LENGTH_SHORT).show();rebuild();});});}
    private void checkRoot(boolean force){executor.execute(()->{RootStatus status=XbsRootApi.checkRoot(this,force);runOnUiThread(()->{if(force)Toast.makeText(this,status.summary(),Toast.LENGTH_LONG).show();rebuild();});});}
    private void sampleProcesses(){executor.execute(()->{ProcessSnapshot snapshot=ProcessRepository.load(this,true);runOnUiThread(()->{Toast.makeText(this,snapshot.rootAvailable?"Process sample refreshed":snapshot.error,Toast.LENGTH_SHORT).show();rebuild();});});}
    private void refreshAppCache(){executor.execute(()->{AppCatalog.invalidate(this);List<InstalledApp> apps=AppCatalog.load(this,true);runOnUiThread(()->Toast.makeText(this,"Cached "+apps.size()+" installed apps",Toast.LENGTH_SHORT).show());});}
    private void cycleToastMode(){int next=(AppSettings.toastMode(this)+1)%4;AppSettings.setToastMode(this,next);rebuild();}
    private void cycleCommandNotificationMode(){int next=NotificationUxPolicy.nextResultMode(AppSettings.commandResultNotificationMode(this));AppSettings.setCommandResultNotificationMode(this,next);rebuild();}
    private void requestNotificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQUEST_NOTIFICATIONS);}
    private void openNotificationSettings(){Intent i=new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);}
    private void openNotificationChannel(String channelId){startActivity(NotificationController.channelSettingsIntent(this,channelId));}

    private void copySupportBundle(){String bundle=SupportBundleBuilder.build(this);((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("XBS support bundle",bundle));Toast.makeText(this,"Support bundle copied",Toast.LENGTH_SHORT).show();}
    private void shareSupportBundle(){String bundle=SupportBundleBuilder.build(this);Intent send=IntentSecurityPolicy.textShare("XBS Companion support bundle",bundle);startActivity(Intent.createChooser(send,"Share XBS support bundle"));}
    private void revealRunFromIntent(View anchor){String runId=IntentSecurityPolicy.internalId(getIntent(),"run_id",96);if(runId.isEmpty())return;getIntent().removeExtra("run_id");anchor.post(()->{RunRecord record=RunStore.find(this,runId);if(record!=null)showRun(record);});}
    private void showRun(RunRecord r){String body=RunDetailFormatter.detailBody(r);AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(r.title).setMessage(body).setNegativeButton("Close",null).setPositiveButton("Copy",(d,w)->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("XBS result",body));Toast.makeText(this,"Copied",Toast.LENGTH_SHORT).show();});if(RunDetailFormatter.isActive(r)){if(RunStore.isStaleActive(this,r))builder.setNeutralButton("Force finalize",(d,w)->forceFinalize(r));else builder.setNeutralButton("Cancel run",(d,w)->cancelRun(r));}builder.show();}
    private void cancelRun(RunRecord r){if(r==null||r.runId.trim().isEmpty())return;RootCommandService.requestCancel(this,r.runId);Toast.makeText(this,"Cancelling "+r.title,Toast.LENGTH_SHORT).show();rebuild();}
    private void forceFinalize(RunRecord r){if(r==null||r.runId.trim().isEmpty())return;if(RunStore.forceFinalizeStale(this,r.runId,"Force-finalized stale active command; no live foreground owner remains"))Toast.makeText(this,"Stale command finalized",Toast.LENGTH_SHORT).show();else Toast.makeText(this,"Command still appears live; cancel first",Toast.LENGTH_SHORT).show();rebuild();}
    private void retryRun(RunRecord r){RunRetryPolicy.Decision decision=RunRetryPolicy.evaluate(r);if(!decision.allowed){Toast.makeText(this,decision.reason,Toast.LENGTH_SHORT).show();return;}if(decision.requiresConfirmation){new AlertDialog.Builder(this).setTitle(decision.title).setMessage(decision.message).setNegativeButton("Cancel",null).setPositiveButton("Retry",(d,w)->launchRetry(decision)).show();return;}launchRetry(decision);}
    private void launchRetry(RunRetryPolicy.Decision decision){CommandLaunchResult result=RootCommandRunner.runCommand(this,decision.actionId,decision.title,decision.description,decision.command,decision.destructive,null,ExecutionSource.APP);Toast.makeText(this,result.started?"Retry started":result.error,Toast.LENGTH_SHORT).show();rebuild();}
    private void confirmClearFinished(){new AlertDialog.Builder(this).setTitle("Clear finished runs?").setMessage("Running commands stay visible; completed, failed, cancelled and timed-out records are removed.").setNegativeButton("Cancel",null).setPositiveButton("Clear",(d,w)->{RunStore.clearFinished(this);rebuild();}).show();}
    private static String ram(long kb){if(kb>=1048576L)return String.format(Locale.US,"%.2f GB",kb/1048576.0);return String.format(Locale.US,"%.1f MB",kb/1024.0);}
    private static String ageLabel(long ms){if(ms<1000)return "now";if(ms<60000)return (ms/1000)+"s";return (ms/60000)+"m";}
}
